7	interface QuoteStep {
8	  op: "quote";
9	  items: Item[];
10	}
11	
12	interface ClaimStep {
13	  op: "claim";
14	  policy: number;
15	  incident: Incident;
16	}
17	
18	type Step = QuoteStep | ClaimStep;
19	
20	interface Scenario {
21	  customer: Customer;
22	  steps: Step[];
23	}
24	
25	type Result = { premium: number } | { payout: number; remainingCap: number };
26	
27	interface Policy {
28	  items: Item[];
29	  remainingCap: number;
30	}
31	
32	// The office works through a scenario's steps in order: each quote creates a
33	// policy a later claim can draw on, and each claim leaves that policy with
34	// less cap for the next one.
35	function resultsFor(scenario: Scenario): Result[] {
36	  const policies = new Map<number, Policy>();
37	  let quoteCount = 0;
38	
39	  return scenario.steps.map((step, stepIndex) => {
40	    if (step.op === "quote") {
41	      const premium = quote(scenario.customer, step.items, quoteCount);
42	      quoteCount += 1;
43	      policies.set(stepIndex, {
44	        items: step.items,
45	        remainingCap: capOf(step.items),
46	      });
47	      return { premium };
48	    }
49	
50	    const policy = policies.get(step.policy);
51	    if (policy === undefined) {
52	      throw new Error(`Step ${step.policy} did not create a policy to claim on`);
53	    }
54	    const settlement = claim(policy.items, policy.remainingCap, step.incident);
55	    policy.remainingCap = settlement.remainingCap;
56	    return settlement;
57	  });
58	}
59	
60	function main(): void {
61	  const scenario = JSON.parse(readFileSync(0, "utf8")) as Scenario;
62	  process.stdout.write(JSON.stringify({ results: resultsFor(scenario) }));
63	}
64	
65	try {
66	  main();
67	} catch (error) {
68	  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
69	  process.exit(1);
70	}
