1	import {
2	  admitDamages,
3	  type Damage,
4	  type SettledDamage,
5	  settledDamagesOf,
6	} from "./policy.js";
7	import type { Item } from "./price-list.js";
8	import { reimbursementShareOf } from "./reimbursement.js";
9	import { roundAmountPaidInMHPCOsFavour } from "./rounding.js";
10	
11	export type { Damage };
12	
13	export interface Incident {
14	  cause: string;
15	  damages: Damage[];
16	}
17	
18	export interface ClaimResult {
19	  payout: number;
20	  remainingCap: number;
21	}
22	
23	// A deductible of 100 G applies per damage event, that is, once per
24	// damaged item rather than once per incident.
25	const DEDUCTIBLE_PER_DAMAGE = 100;
26	
27	// What a single settled damage is worth: the reimbursable share of the damage
28	// amount, less the deductible the office withholds from every damage event.
29	// Which item the report refers to is settled before this point, so the
30	// valuation turns on the item itself, never on the policy.
31	function valueOf({ damagedItem, amount }: SettledDamage): number {
32	  return amount * reimbursementShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
33	}
34	
35	// What the incident is worth to the claimant: each reported damage is matched
36	// to the covered item it refers to, and every match is valued separately.
37	function incidentValueOf(items: Item[], incident: Incident): number {
38	  return settledDamagesOf(items, incident.damages).reduce(
39	    (total, settledDamage) => total + valueOf(settledDamage),
40	    0,
41	  );
42	}
43	
44	// How a claim settles against the policy's remaining cap. The office never
45	// pays more than the cap still allows, so a claim worth more than that is
46	// reduced to what remains rather than refused, and the cap falls by what the
47	// office actually paid rather than by what the claim was worth. These two
48	// decisions move together whenever the office revises its cap rules, and
49	// neither touches what an incident is worth.
50	function settleAgainstCap(
51	  remainingCap: number,
52	  incidentValue: number,
53	): ClaimResult {
54	  const payout = roundAmountPaidInMHPCOsFavour(
55	    Math.min(incidentValue, remainingCap),
56	  );
57	  return { payout, remainingCap: remainingCap - payout };
58	}
59	
60	// Settling an incident against a policy: what the incident is worth to the
61	// claimant, limited by what the policy's cap still allows.
62	export function claim(
63	  items: Item[],
64	  remainingCap: number,
65	  incident: Incident,
66	): ClaimResult {
67	  admitDamages(incident.damages);
68	  return settleAgainstCap(remainingCap, incidentValueOf(items, incident));
69	}
