1	import { insuranceValueOf, type Item } from "./price-list.js";
2	
3	export interface Damage {
4	  itemType: string;
5	  amount: number;
6	}
7	
8	// A reported damage once the office has decided which covered item answers
9	// for it: the amount to value, bound to the item it will be valued against.
10	export interface SettledDamage {
11	  damagedItem: Item;
12	  amount: number;
13	}
14	
15	// The MHPCO caps the total payout per policy at twice the insurance sum.
16	const PAYOUT_CAP_MULTIPLE = 2;
17	
18	export function insuranceSumOf(items: Item[]): number {
19	  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
20	}
21	
22	export function capOf(items: Item[]): number {
23	  return insuranceSumOf(items) * PAYOUT_CAP_MULTIPLE;
24	}
25	
26	// Whether the office admits the reports at all, before it asks which items
27	// answer for them. A damage report states how much damage an item took, so a
28	// negative amount is not a reduced payout but a report the office refuses.
29	// The office refuses the whole claim, so every report is admitted before any
30	// is settled. Further admissibility rules belong here, alongside this one.
31	export function admitDamages(damages: Damage[]): void {
32	  for (const damage of damages) {
33	    if (damage.amount < 0) {
34	      throw new Error(
35	        `A damage amount cannot be negative, but "${damage.itemType}" reports ${damage.amount}`,
36	      );
37	    }
38	  }
39	}
40	
41	// Which covered item answers for each reported damage. The office only settles
42	// damage to items it actually covers, and each covered item answers for at
43	// most one damage, so a type outside the policy -- or reported more often
44	// than the policy covers it -- is not a smaller payout but a claim it refuses.
45	export function settledDamagesOf(
46	  items: Item[],
47	  damages: Damage[],
48	): SettledDamage[] {
49	  const unclaimedItems = [...items];
50	  return damages.map((damage) => {
51	    const index = unclaimedItems.findIndex(
52	      (item) => item.type === damage.itemType,
53	    );
54	    if (index === -1) {
55	      throw new Error(
56	        `The policy does not cover an item of type "${damage.itemType}"`,
57	      );
58	    }
59	    return {
60	      damagedItem: unclaimedItems.splice(index, 1)[0],
61	      amount: damage.amount,
62	    };
63	  });
64	}
