50	// The customer's relationship with MHPCO as of this quote: how long they have
51	// been doing business and how many contracts they have already taken out.
52	interface CustomerStanding {
53	  yearsWithMHPCO: number;
54	  previousQuoteCount: number;
55	}
56	
57	function isLongStanding(standing: CustomerStanding): boolean {
58	  return standing.yearsWithMHPCO >= LOYALTY_YEARS;
59	}
60	
61	function isFollowUpContract(standing: CustomerStanding): boolean {
62	  return standing.previousQuoteCount > 0;
63	}
64	
65	// Discounts earned by the customer's standing, in contrast to the initial
66	// assessment surcharge, which the MHPCO levies on every newly quoted policy
67	// regardless of customer history.
68	function standingDiscountRateOf(standing: CustomerStanding): number {
69	  return (
70	    (isLongStanding(standing) ? LOYALTY_DISCOUNT_RATE : 0) +
71	    (isFollowUpContract(standing) ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0)
72	  );
73	}
74	
75	// Policy-wide modifiers apply to the policy base premium (the sum of all
76	// item base premiums), in contrast to the item-specific risk surcharges.
77	function policyWideModifiersOf(
78	  standing: CustomerStanding,
79	  policyBasePremium: number,
80	): number {
81	  return (
82	    firstInsuranceSurchargeOf(policyBasePremium) -
83	    policyBasePremium * standingDiscountRateOf(standing)
84	  );
85	}
86	
87	export function quote(
88	  customer: Customer,
89	  items: Item[],
90	  previousQuoteCount: number,
91	): number {
92	  const standing = { ...customer, previousQuoteCount };
93	  const policyBasePremium = policyBasePremiumOf(items);
94	  const premium =
95	    policyBasePremium +
96	    itemRiskSurchargesOf(items) +
97	    policyWideModifiersOf(standing, policyBasePremium) +
98	    PROCESSING_FEE;
99	  return roundAmountChargedInMHPCOsFavour(premium);
100	}
