// What the office's ledger carries from one step to the next: the policies
// earlier quotes opened, and how many contracts the customer has taken out so
// far. Each step reads the ledger and leaves it changed for the steps after.
class Ledger {
  private readonly policies = new Map<number, Policy>();
  private quoteCount = 0;

  // A quote opens a policy the customer's later claims can draw on, and counts
  // towards the contracts that make the next quote a follow-up.
  openPolicy(stepIndex: number, items: Item[]): number {
    const previousQuoteCount = this.quoteCount;
    this.quoteCount += 1;
    this.policies.set(stepIndex, { items, remainingCap: capOf(items) });
    return previousQuoteCount;
  }

  // A claim refers to the policy an earlier step opened, and leaves it with
  // less cap for the claims after it.
  policyOpenedBy(stepIndex: number): Policy {
    const policy = this.policies.get(stepIndex);
    if (policy === undefined) {
      throw new Error(`Step ${stepIndex} did not create a policy to claim on`);
    }
    return policy;
  }
}

// How the office works a single step against the ledger it has built up so far.
function resultOf(
  customer: Customer,
  ledger: Ledger,
  step: Step,
  stepIndex: number,
): Result {
  if (step.op === "quote") {
    const previousQuoteCount = ledger.openPolicy(stepIndex, step.items);
    return { premium: quote(customer, step.items, previousQuoteCount) };
  }

  const policy = ledger.policyOpenedBy(step.policy);
  const settlement = claim(policy.items, policy.remainingCap, step.incident);
  policy.remainingCap = settlement.remainingCap;
  return settlement;
}

// The office works through a scenario's steps in order, each step answered
// against everything the earlier steps left behind.
export function resultsFor(scenario: Scenario): Result[] {
  const ledger = new Ledger();
  return scenario.steps.map((step, stepIndex) =>
    resultOf(scenario.customer, ledger, step, stepIndex),
  );
}
